using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [Description("Search the web for information on a topic. Returns a list of results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        try
        {
            // Uses the Bing Web Search API.
            // Set the environment variable BING_SEARCH_API_KEY to your key.
            var requestUri = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count={maxResults}&mkt=en-US";

            var response = await _httpClient.GetAsync(requestUri);
            response.EnsureSuccessStatusCode();

            using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());

            var results = new List<string>();
            if (doc.RootElement.TryGetProperty("webPages", out var webPages) &&
                webPages.TryGetProperty("value", out var values))
            {
                foreach (var item in values.EnumerateArray())
                {
                    var title = item.GetProperty("name").GetString();
                    var url = item.GetProperty("url").GetString();
                    var snippet = item.GetProperty("snippet").GetString();
                    results.Add($"**{title}**\nURL: {url}\n{snippet}");
                }
            }

            return results.Count > 0
                ? string.Join("\n---\n", results)
                : "No results found for the query.";
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Ensure BING_SEARCH_API_KEY is set correctly.";
        }
    }

    [Description("Fetch and read the text content of a specific web page URL. Use this to get detailed information from a search result.")]
    public async Task<string> ReadWebPageAsync(
        [Description("The full URL of the web page to read")] string url,
        [Description("Maximum number of characters to return")] int maxLength = 5000)
    {
        maxLength = Math.Clamp(maxLength, 500, 15000);

        try
        {
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.Add("Accept", "text/html");
            request.Headers.Add("User-Agent", "ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();

            var html = await response.Content.ReadAsStringAsync();

            // Crude HTML-to-text: strip tags and collapse whitespace.
            var text = StripHtml(html);
            if (text.Length > maxLength)
            {
                text = text[..maxLength] + "\n[...truncated]";
            }

            return string.IsNullOrWhiteSpace(text)
                ? "Could not extract readable content from the page."
                : text;
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
        {
            return $"Failed to read page: {ex.Message}";
        }
    }

    private static string StripHtml(string html)
    {
        // Remove script/style blocks, then all tags, then collapse whitespace.
        var text = System.Text.RegularExpressions.Regex.Replace(html, @"<(script|style)[^>]*>.*?</\1>", " ", System.Text.RegularExpressions.RegexOptions.Singleline | System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        text = System.Text.RegularExpressions.Regex.Replace(text, @"<[^>]+>", " ");
        text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
        return System.Net.WebUtility.HtmlDecode(text).Trim();
    }
}

using System.ComponentModel;

namespace ResearchAgent.Tools;

public sealed class NoteTool
{
    private readonly List<NoteEntry> _notes = [];

    [Description("Save a research note with a category tag. Use this to record key findings, facts, and sources discovered during research.")]
    public string SaveNote(
        [Description("A short category for the note (e.g. 'definition', 'statistic', 'source', 'key-finding')")] string category,
        [Description("The content of the note")] string content,
        [Description("The source URL or reference, if any")] string? source = null)
    {
        var entry = new NoteEntry(category, content, source, DateTime.UtcNow);
        _notes.Add(entry);
        return $"Note #{_notes.Count} saved under '{category}'.";
    }

    [Description("Retrieve all saved research notes, optionally filtered by category.")]
    public string GetNotes(
        [Description("Optional category to filter notes by. Leave empty to get all notes.")] string? category = null)
    {
        var filtered = string.IsNullOrWhiteSpace(category)
            ? _notes
            : _notes.Where(n => n.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return string.IsNullOrWhiteSpace(category)
                ? "No notes saved yet."
                : $"No notes found under category '{category}'.";
        }

        var lines = filtered.Select((n, i) =>
        {
            var src = string.IsNullOrWhiteSpace(n.Source) ? "" : $"\n   Source: {n.Source}";
            return $"[{n.Category}] {n.Content}{src}";
        });

        return string.Join("\n\n", lines);
    }

    private sealed record NoteEntry(string Category, string Content, string? Source, DateTime Timestamp);
}

