+            using var doc = await JsonDocument.ParseAsync(await response.Content.ReadAsStreamAsync());
+
+            var results = new List<string>();
+            if (doc.RootElement.TryGetProperty("webPages", out var webPages) &&
+                webPages.TryGetProperty("value", out var values))
+            {
+                foreach (var item in values.EnumerateArray())
+                {
+                    var title = item.GetProperty("name").GetString();
+                    var url = item.GetProperty("url").GetString();
+                    var snippet = item.GetProperty("snippet").GetString();
+                    results.Add($"**{title}**\nURL: {url}\n{snippet}");
+                }
+            }
+
+            return results.Count > 0
+                ? string.Join("\n---\n", results)
+                : "No results found for the query.";
+        }
+        catch (HttpRequestException ex)
+        {
+            return $"Search failed: {ex.Message}. Ensure BING_SEARCH_API_KEY is set correctly.";
+        }
+    }
+
+    [Description("Fetch and read the text content of a specific web page URL. Use this to get detailed information from a search result.")]
+    public async Task<string> ReadWebPageAsync(
+        [Description("The full URL of the web page to read")] string url,
+        [Description("Maximum number of characters to return")] int maxLength = 5000)
+    {
+        maxLength = Math.Clamp(maxLength, 500, 15000);
+
+        try
+        {
+            var request = new HttpRequestMessage(HttpMethod.Get, url);
+            request.Headers.Add("Accept", "text/html");
+            request.Headers.Add("User-Agent", "ResearchAgent/1.0");
+
+            var response = await _httpClient.SendAsync(request);
+            response.EnsureSuccessStatusCode();
+
+            var html = await response.Content.ReadAsStringAsync();
+
+            // Crude HTML-to-text: strip tags and collapse whitespace.
+            var text = StripHtml(html);
+            if (text.Length > maxLength)
+            {
+                text = text[..maxLength] + "\n[...truncated]";
+            }
+
+            return string.IsNullOrWhiteSpace(text)
+                ? "Could not extract readable content from the page."
+                : text;
+        }
+        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
+        {
+            return $"Failed to read page: {ex.Message}";
+        }
+    }
+
+    private static string StripHtml(string html)
+    {
+        // Remove script/style blocks, then all tags, then collapse whitespace.
+        var text = System.Text.RegularExpressions.Regex.Replace(html, @"<(script|style)[^>]*>.*?</\1>", " ", System.Text.RegularExpressions.RegexOptions.Singleline | System.Text.RegularExpressions.RegexOptions.IgnoreCase);
+        text = System.Text.RegularExpressions.Regex.Replace(text, @"<[^>]+>", " ");
+        text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ");
+        return System.Net.WebUtility.HtmlDecode(text).Trim();
+    }
+}
