using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

// ── Configuration ──────────────────────────────────────────────────────
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

var bingKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");
if (string.IsNullOrEmpty(bingKey))
{
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine("⚠  BING_SEARCH_API_KEY not set — web search calls will fail.");
    Console.WriteLine("   Get a key at https://aka.ms/bingapisignup");
    Console.ResetColor();
}

// Pin to a specific model version to reduce behavioural drift.
const string modelId = "gpt-4o-mini-2024-07-18";

// ── Services ───────────────────────────────────────────────────────────
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddHttpClient("BingSearch", client =>
{
    if (!string.IsNullOrEmpty(bingKey))
    {
        client.DefaultRequestHeaders.Add("Ocp-Apim-Subscription-Key", bingKey);
    }
    client.Timeout = TimeSpan.FromSeconds(15);
});

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(openAiKey)));

var sp = services.BuildServiceProvider();

// ── Tool instances ─────────────────────────────────────────────────────
var httpFactory = sp.GetRequiredService<IHttpClientFactory>();
var searchTool = new WebSearchTool(httpFactory.CreateClient("BingSearch"));
var noteTool = new NoteTool();

var tools = new AIFunctionFactory().Create(searchTool)
    .Concat(new AIFunctionFactory().Create(noteTool))
    .ToList();

// ── Agent ──────────────────────────────────────────────────────────────
var chatClient = sp.GetRequiredService<IChatClient>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly
        and produce a well-structured summary.

        Workflow:
        1. Break the topic into 2-3 sub-questions.
        2. Use SearchWeb to find information for each sub-question.
        3. Use ReadWebPage to read the most promising results in detail.
        4. Use SaveNote to record every key finding, statistic, or quote
           with its source URL.
        5. After researching, use GetNotes to review your notes.
        6. Produce a final markdown summary with:
           - An overview paragraph
           - Key findings as bullet points
           - A Sources section listing all URLs consulted

        Be thorough but concise. Cite your sources.
        """,
};

// ── Run ────────────────────────────────────────────────────────────────
Console.ForegroundColor = ConsoleColor.Cyan;
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║      🔍 Research Agent               ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    Console.WriteLine("\nResearching... (this may take a minute)\n");

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary:\n\n{topic}"),
    };

    var options = new AgentInvokeOptions
    {
        MaximumIterations = 10,
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 4096,
            Tools = [.. tools],
        },
    };

    try
    {
        string? finalResponse = null;
        await foreach (var message in agent.InvokeStreamingAsync(history, options))
        {
            if (!string.IsNullOrEmpty(message.Content))
            {
                Console.Write(message.Content);
                finalResponse = (finalResponse ?? "") + message.Content;
            }
        }

        Console.WriteLine("\n");
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"\nError: {ex.Message}");
        Console.ResetColor();
    }
}

Console.WriteLine("Goodbye!");

